<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Expense Tracker</title>
<style>
  :root {
    --bg: #f4f6f8;
    --card: #ffffff;
    --ink: #1e2530;
    --muted: #66707d;
    --line: #dde2e8;
    --accent: #2f6fed;
    --danger: #c8322b;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 24px 16px 64px;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.45;
  }
  .wrap { max-width: 880px; margin: 0 auto; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  .sub { color: var(--muted); font-size: 13px; margin: 0 0 20px; }
  section {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 18px;
  }
  h2 { font-size: 14px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin: 0 0 12px; }
  .grid { display: flex; flex-wrap: wrap; gap: 12px; }
  .field { display: flex; flex-direction: column; gap: 4px; flex: 1 1 140px; min-width: 130px; }
  label { font-size: 12px; color: var(--muted); }
  input, select, button {
    font: inherit;
    padding: 8px 10px;
    border: 1px solid var(--line);
    border-radius: 6px;
    background: #fff;
    color: inherit;
  }
  input:focus, select:focus { outline: 2px solid rgba(47,111,237,.35); outline-offset: 1px; }
  #add-expense {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
    cursor: pointer;
    align-self: flex-end;
    padding: 8px 18px;
  }
  #add-expense:hover { filter: brightness(1.07); }
  #form-error {
    color: var(--danger);
    font-size: 13px;
    min-height: 18px;
    margin-top: 10px;
  }
  #form-error:empty { min-height: 0; margin-top: 0; }
  table { width: 100%; border-collapse: collapse; }
  th, td { text-align: left; padding: 8px 6px; border-bottom: 1px solid var(--line); font-size: 14px; }
  th { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
  td.amt, th.amt { text-align: right; font-variant-numeric: tabular-nums; }
  .exp-del {
    background: #fff;
    border: 1px solid var(--line);
    color: var(--danger);
    cursor: pointer;
    padding: 3px 9px;
    border-radius: 6px;
    font-size: 13px;
  }
  .exp-del:hover { background: #fdeceb; border-color: var(--danger); }
  .cat-badge {
    display: inline-block;
    background: #eef2f8;
    border-radius: 20px;
    padding: 1px 10px;
    font-size: 12px;
  }
  .totals { display: flex; flex-wrap: wrap; gap: 10px; align-items: baseline; }
  .cat-total {
    background: #eef2f8;
    border-radius: 6px;
    padding: 6px 10px;
    font-size: 13px;
    font-variant-numeric: tabular-nums;
  }
  .total-line { font-size: 18px; font-weight: 600; margin: 0 0 12px; }
  #total { font-variant-numeric: tabular-nums; }
  #empty { color: var(--muted); font-size: 14px; padding: 10px 4px; }
  .row-actions { width: 1%; white-space: nowrap; }
  .note { color: var(--muted); }
</style>
</head>
<body>
<div class="wrap">
  <h1>Expense Tracker</h1>
  <p class="sub">Everything is stored locally in your browser.</p>

  <section>
    <h2>Add an expense</h2>
    <form id="expense-form" novalidate>
      <div class="grid">
        <div class="field">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" min="0" placeholder="0.00" autocomplete="off">
        </div>
        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div class="field">
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div class="field" style="flex: 2 1 200px;">
          <label for="note">Note (optional)</label>
          <input type="text" id="note" placeholder="Coffee with Sam" autocomplete="off">
        </div>
        <button type="submit" id="add-expense">Add</button>
      </div>
      <div id="form-error" role="alert"></div>
    </form>
  </section>

  <section>
    <h2>Filters</h2>
    <div class="grid">
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field">
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div class="field">
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
      <div class="field" style="justify-content: flex-end;">
        <button type="button" id="clear-filters">Clear filters</button>
      </div>
    </div>
  </section>

  <section>
    <h2>Summary</h2>
    <p class="total-line">Total: <span id="total">0.00</span></p>
    <div class="totals" id="cat-totals">
      <span class="cat-total" data-cat="groceries">groceries: 0.00</span>
      <span class="cat-total" data-cat="transport">transport: 0.00</span>
      <span class="cat-total" data-cat="bills">bills: 0.00</span>
      <span class="cat-total" data-cat="fun">fun: 0.00</span>
    </div>
  </section>

  <section>
    <h2>Expenses</h2>
    <table>
      <thead>
        <tr>
          <th class="amt">Amount</th>
          <th>Category</th>
          <th>Date</th>
          <th>Note</th>
          <th class="row-actions"></th>
        </tr>
      </thead>
      <tbody id="expense-list"></tbody>
    </table>
    <div id="empty">No expenses to show.</div>
  </section>
</div>

<script>
(function () {
  'use strict';

  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
  var STORAGE_KEY = 'expense-tracker-v1';

  var form = document.getElementById('expense-form');
  var amountEl = document.getElementById('amount');
  var categoryEl = document.getElementById('category');
  var dateEl = document.getElementById('date');
  var noteEl = document.getElementById('note');
  var errorEl = document.getElementById('form-error');

  var filterCatEl = document.getElementById('filter-category');
  var filterFromEl = document.getElementById('filter-from');
  var filterToEl = document.getElementById('filter-to');
  var clearFiltersEl = document.getElementById('clear-filters');

  var listEl = document.getElementById('expense-list');
  var emptyEl = document.getElementById('empty');
  var totalEl = document.getElementById('total');

  var expenses = [];

  function load() {
    var raw = null;
    try { raw = localStorage.getItem(STORAGE_KEY); } catch (e) { raw = null; }
    if (!raw) return [];
    var parsed;
    try { parsed = JSON.parse(raw); } catch (e) { return []; }
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(function (item) {
      return item && typeof item === 'object' &&
        isFinite(Number(item.amount)) && Number(item.amount) > 0 &&
        typeof item.date === 'string' && item.date;
    }).map(function (item, i) {
      return {
        id: String(item.id || ('e' + i + '-' + item.date)),
        amount: Number(item.amount),
        category: CATEGORIES.indexOf(item.category) >= 0 ? item.category : CATEGORIES[0],
        date: item.date,
        note: typeof item.note === 'string' ? item.note : '',
        created: Number(item.created) || 0
      };
    });
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses)); } catch (e) { /* storage unavailable */ }
  }

  var seq = 0;
  function nextId() {
    seq += 1;
    return 'exp-' + seq + '-' + String(expenses.length) + '-' + String(seq * 7919);
  }

  function fmt(n) {
    return (Math.round(n * 100) / 100).toFixed(2);
  }

  // Newest first: latest date wins, ties broken by insertion order (later added first).
  function sorted() {
    return expenses.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return b.created - a.created;
    });
  }

  function isVisible(exp) {
    var cat = filterCatEl.value;
    if (cat !== 'all' && exp.category !== cat) return false;
    var from = filterFromEl.value;
    var to = filterToEl.value;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  function render() {
    listEl.textContent = '';
    var rows = sorted();
    var visibleCount = 0;
    var total = 0;
    var catTotals = {};
    CATEGORIES.forEach(function (c) { catTotals[c] = 0; });

    rows.forEach(function (exp) {
      var tr = document.createElement('tr');
      tr.className = 'expense';
      tr.setAttribute('data-id', exp.id);
      tr.setAttribute('data-category', exp.category);
      tr.setAttribute('data-date', exp.date);
      tr.setAttribute('data-amount', fmt(exp.amount));

      var tdAmount = document.createElement('td');
      tdAmount.className = 'amt';
      tdAmount.textContent = fmt(exp.amount);
      tr.appendChild(tdAmount);

      var tdCat = document.createElement('td');
      var badge = document.createElement('span');
      badge.className = 'cat-badge';
      badge.textContent = exp.category;
      tdCat.appendChild(badge);
      tr.appendChild(tdCat);

      var tdDate = document.createElement('td');
      tdDate.textContent = exp.date;
      tr.appendChild(tdDate);

      var tdNote = document.createElement('td');
      tdNote.className = 'note';
      tdNote.textContent = exp.note || '';
      tr.appendChild(tdNote);

      var tdActions = document.createElement('td');
      tdActions.className = 'row-actions';
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'exp-del';
      del.textContent = 'Delete';
      del.setAttribute('data-id', exp.id);
      del.setAttribute('aria-label', 'Delete expense of ' + fmt(exp.amount) + ' on ' + exp.date);
      tdActions.appendChild(del);
      tr.appendChild(tdActions);

      if (isVisible(exp)) {
        visibleCount += 1;
        total += exp.amount;
        catTotals[exp.category] += exp.amount;
      } else {
        tr.style.display = 'none';
        tr.hidden = true;
      }

      listEl.appendChild(tr);
    });

    totalEl.textContent = fmt(total);
    CATEGORIES.forEach(function (c) {
      var el = document.querySelector('.cat-total[data-cat="' + c + '"]');
      if (el) el.textContent = c + ': ' + fmt(catTotals[c]);
    });

    emptyEl.style.display = visibleCount === 0 ? 'block' : 'none';
    emptyEl.textContent = expenses.length === 0
      ? 'No expenses yet — add one above.'
      : 'No expenses match the current filters.';
  }

  form.addEventListener('submit', function (ev) {
    ev.preventDefault();

    var rawAmount = amountEl.value.trim();
    var date = dateEl.value;

    if (rawAmount === '') {
      errorEl.textContent = 'Please enter an amount.';
      return;
    }
    var amount = Number(rawAmount);
    if (!isFinite(amount) || rawAmount !== rawAmount) {
      errorEl.textContent = 'Amount must be a number.';
      return;
    }
    if (isNaN(amount)) {
      errorEl.textContent = 'Amount must be a number.';
      return;
    }
    if (amount <= 0) {
      errorEl.textContent = 'Amount must be greater than zero.';
      return;
    }
    if (!date) {
      errorEl.textContent = 'Please pick a date.';
      return;
    }

    expenses.push({
      id: nextId(),
      amount: Math.round(amount * 100) / 100,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim(),
      created: ++createdCounter
    });

    save();
    errorEl.textContent = '';
    amountEl.value = '';
    noteEl.value = '';
    amountEl.focus();
    render();
  });

  listEl.addEventListener('click', function (ev) {
    var btn = ev.target.closest ? ev.target.closest('.exp-del') : null;
    if (!btn) return;
    var id = btn.getAttribute('data-id');
    expenses = expenses.filter(function (e) { return e.id !== id; });
    save();
    render();
  });

  [filterCatEl, filterFromEl, filterToEl].forEach(function (el) {
    el.addEventListener('change', render);
    el.addEventListener('input', render);
  });

  clearFiltersEl.addEventListener('click', function () {
    filterCatEl.value = 'all';
    filterFromEl.value = '';
    filterToEl.value = '';
    render();
  });

  var createdCounter = 0;
  expenses = load();
  expenses.forEach(function (e) {
    if (!e.created) e.created = ++createdCounter;
    else if (e.created > createdCounter) createdCounter = e.created;
  });

  // Default the entry date to today for convenience.
  (function setToday() {
    var d = new Date();
    var mm = String(d.getMonth() + 1).padStart(2, '0');
    var dd = String(d.getDate()).padStart(2, '0');
    dateEl.value = d.getFullYear() + '-' + mm + '-' + dd;
  })();

  render();
})();
</script>
</body>
</html>
